#include <list>
using namespace std;
typedef list<int> LISTINT;
LISTINT listInt; LISTINT::iterator i;
listInt.insert(listInt.begin(), 2);
listInt.insert(listInt.begin(), 1);
listInt.insert(listInt.end(), 3);
for (i = listInt.begin(); i != listInt.end(); i++) cout << " " << *i;
结果为 1 2 3：两次头插使顺序反转（2 之后 1 插到最前），尾插 3 追加到最后。
